from urllib.parse import urlparse, urlunparse, parse_qs, urlencode


def apply_rewrite_rules(rules, urls):
    """
    Apply a list of URL rewrite rules to a list of URLs in order.
    For each URL, the first matching rule is applied; if none match, the original URL is returned.
    If a rule action is 'block', return None for that URL.
    """

    def matches_path_prefix(url, match_value):
        path = urlparse(url).path or '/'
        return path.startswith(match_value)

    def matches_host(url, match_value):
        host = urlparse(url).hostname
        if match_value == '':
            return False
        if match_value.endswith('*.'):
            base = match_value[:-2]
            return host == base or (len(host) > len(base) + 1 and host.startswith(base + '.'))
        return host == match_value

    def matches_query_param(url, param_name):
        query = urlparse(url).query
        if not query:
            return False
        params = dict(parse_qs(query))
        # Handle list of values from parse_qs
        for k in params:
            if param_name in k or k == param_name:
                return True
        return any(k == param_name for k in params)

    def apply_strip_prefix(url, prefix):
        parsed = urlparse(url)
        path = parsed.path or '/'
        new_path = path[len(prefix):]
        if not new_path:
            new_path = '/'
        return urlunparse((parsed.scheme, parsed.netloc, new_path, parsed.params, parsed.query, parsed.fragment))

    def apply_redirect_host(url, host):
        parsed = urlparse(url)
        port = f":{parsed.port}" if parsed.port else ''
        netloc = f"{host}{port}"
        return urlunparse((parsed.scheme, netloc, parsed.path, parsed.params, parsed.query, parsed.fragment))

    def apply_add_query_param(url, param):
        key, value = param.split('=', 1) if '=' in param else (param, 'value')
        parsed = urlparse(url)
        query_params = parse_qs(parsed.query) or {}
        existing_values = query_params.get(key, [])
        new_value = value + f"_{len(existing_values)}" if existing_values else value
        query_params[key] = [new_value]
        return urlunparse((parsed.scheme, parsed.netloc, parsed.path, parsed.params, urlencode(query_params, doseq=True), parsed.fragment))

    for url in urls:
        parsed = urlparse(url)
        original = None
        applied = False
        blocked = False

        for rule in rules:
            match_type = rule['match_type']
            match_value = rule['match_value']
            action = rule['action']

            matched = False
            if match_type == 'path_prefix':
                matched = matches_path_prefix(url, match_value)
            elif match_type == 'host':
                matched = matches_host(url, match_value)
            elif match_type == 'query_param':
                matched = matches_query_param(url, match_value)

            if not matched:
                continue

            # Apply action
            if action == 'block':
                blocked = True
                break
            elif action == 'strip_prefix':
                original = apply_strip_prefix(url, rule.get('action_value', ''))
            elif action == 'redirect_host':
                original = apply_redirect_host(url, rule.get('action_value', ''))
            elif action == 'add_query_param':
                original = apply_add_query_param(url, rule.get('action_value', ''))

            applied = True
            break

        if blocked:
            results.append(None)
        elif applied and original is not None:
            results.append(original)
        else:
            results.append(url)

    return results
